function o(t){return new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL"}).format(t||0)}function u(t){if(!t)return"—";const[e,n,r]=t.split("-");return`${r}/${n}/${e}`}function i(){return new Date().toISOString().slice(0,10)}function s(t,e){const n=new Date(t+"T00:00:00");return n.setDate(n.getDate()+e),n.toISOString().slice(0,10)}function f(t,e=0){const n=t.reduce((c,a)=>c+(a.quantity*a.unit_price||0),0),r=Math.max(0,n-(e||0));return{subtotal:n,discount:e||0,total:r}}function l(t,e){return e==="paid"||e==="cancelled"?!1:new Date(t+"T00:00:00")<new Date(new Date().toDateString())}export{u as a,s as b,f as c,o as f,l as i,i as t};
